describe('ToolRegistry', () => {
  it('throws at registration time for an uncompilable schema, naming the tool', () => {
    const registry = new ToolRegistry();
    expect(() => {
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'bad',
          inputSchema: {type: 'invalid_type_here'},
        },
        async () => 'success'
      );
    }).toThrow(/bad_schema_tool/);
  });
});

